ntity\\\": \\\"edward vi\\\", \\\"tail_entity\\\": \\\"protestantism\\\", \\\"relation_type\\\": \\\"religion\\\", \\\"relation_pid\\\": \\\"P140\\\"}, {\\\"text\\\": \\\"The 14th century saw the spread of Sunni Islam among the Tatars .\\\", \\\"head_entity\\\": \\\"tatars\\\", \\\"tail_entity\\\": \\\"sunni islam\\\", \\\"relation_type\\\": \\\"religion\\\", \\\"relation_pid\\\": \\\"P140\\\"}, {\\\"text\\\": \\\"Joseph Francis Busch ( April 18 , 1866—May 31 , 1953 ) was an American prelate of the Catholic Church .\\\", \\\"head_entity\\\": \\\"joseph francis busch\\\", \\\"tail_entity\\\": \\\"catholic church\\\", \\\"relation_type\\\": \\\"religion\\\", \\\"relation_pid\\\": \\\"P140\\\"}, {\\\"text\\\": \\\"Baruch Alter HaCohen Taub ( ) is the founding rabbi and Rabbi Emeritus of the Beth Avraham Yoseph of Toronto Congregation ( BAYT ) , the largest Orthodox congregation in Canada .\\\", \\\"head_entity\\\": \\\"bayt\\\", \\\"tail_entity\\\": \\\"orthodox\\\", \\\"relation_type\\\": \\\"religion\\\", \\\"relation_pid\\\": \\\"P140\\\"}, {\\\"text\\\": \\\"Very quickly , the Armenians were disillusioned : in 449 , Yazdegerd II ordered the nobility to convert to Zoroastrianism .\\\", \\\"head_entity\\\": \\\"yazdegerd ii\\\", \\\"tail_entity\\\": \\\"zoroastrianism\\\", \\\"relation_type\\\": \\\"religion\\\", \\\"relation_pid\\\": \\\"P140\\\"}, {\\\"text\\\": \\\"Luke Booker ( 20 October 1762 – 1 October 1837 ) LL.D. , FRLS was an English Anglican clergyman , poet , and antiquary , with a prolific publication list of sermons and poetry .\\\", \\\"head_entity\\\": \\\"luke booker\\\", \\\"tail_entity\\\": \\\"anglican\\\", \\\"relation_type\\\": \\\"religion\\\", \\\"relation_pid\\\": \\\"P140\\\"}, {\\\"text\\\": \\\"In 2002 , Martini reached the Catholic Church 's mandatory retirement age of 75 and was succeeded in Milan by Dionigi Tettamanzi .\\\", \\\"head_entity\\\": \\\"dionigi tettamanzi\\\", \\\"tail_entity\\\": \\\"catholic church\\\", \\\"relation_type\